content:
:root {
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-primary: #1e293b;
  --text-secondary: #475569;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --primary-color: #3b82f6;
  --hover-bg: #f1f5f9;
  --focus-ring: rgba(59, 130, 246, 0.25);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 900px;
  margin: 40px auto;
  padding: 24px;
  background-color: var(--card-bg);
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
}

.header {
  margin-bottom: 24px;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 16px;
}

.title {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-primary);
}

.search-container {
  margin-bottom: 20px;
}

.search-input {
  width: 100%;
  padding: 12px 16px;
  font-size: 16px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  outline: none;
  background-color: var(--card-bg);
  color: var(--text-primary);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.search-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px var(--focus-ring);
}

.table-container {
  overflow-x: auto;
  border: 1px solid var(--border-color);
  border-radius: 8px;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 15px;
  white-space: nowrap;
}

.employee-table th,
.employee-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
}

.employee-table tbody tr:last-child td {
  border-bottom: none;
}

.employee-table tbody tr:hover {
  background-color: var(--hover-bg);
}

.th-sortable {
  background-color: var(--bg-color);
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s, color 0.2s;
}

.th-sortable:hover {
  background-color: #e2e8f0;
  color: var(--text-primary);
}

.sorted-asc::after {
  content: "";
  display: inline-block;
  width: 0;
  height: 0;
  margin-left: 6px;
  vertical-align: middle;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-bottom: 6px solid var(--primary-color);
}

.sorted-desc::after {
  content: "";
  display: inline-block;
  width: 0;
  height: 0;
  margin-left: 6px;
  vertical-align: middle;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-top: 6px solid var(--primary-color);
}

.no-results {
  text-align: center;
  padding: 32px;
  color: var(--text-muted);
  font-size: 15px;
}

@media (max-width: 640px) {
  .app-container {
    margin: 12px;
    padding: 16px;
    border-radius: 8px;
  }

  .title {
    font-size: 20px;
  }

  .employee-table th,
  .employee-table td {
    padding: 10px 12px;
    font-size: 14px;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
  email: string;
  hireDate: string;
}

export type SortableField = 'id' | 'name' | 'department' | 'age';

export interface EmployeeTableProps {
  employees: Employee[];
  sortField: SortableField;
  sortDirection: 'asc' | 'desc';
  onSort: (field: SortableField) => void;
  filterText: string;
  onFilterChange: (text: string) => void;
}

import { EmployeeTableProps, Employee } from './types';

export default function EmployeeTable({
  employees = [],
  sortField,
  sortDirection,
  onSort,
  filterText = '',
  onFilterChange,
}: EmployeeTableProps) {
  const getSortClass = (field: keyof Employee) => {
    if (sortField !== field) return 'th-sortable';
    return `th-sortable ${sortDirection === 'asc' ? 'sorted-asc' : 'sorted-desc'}`;
  };

  const getAriaSort = (field: keyof Employee): 'ascending' | 'descending' | 'none' => {
    if (sortField !== field) return 'none';
    return sortDirection === 'asc' ? 'ascending' : 'descending';
  };

  return (
    <div>
      <div className="search-container" style={{ position: 'relative' }}>
        <input
          type="text"
          className="search-input"
          placeholder="名前で絞り込み..."
          value={filterText}
          onChange={(e) => onFilterChange(e.target.value)}
          style={{ paddingRight: filterText ? '36px' : '16px' }}
        />
        {filterText && (
          <button
            type="button"
            onClick={() => onFilterChange('')}
            style={{
              position: 'absolute',
              right: '12px',
              top: '50%',
              transform: 'translateY(-50%)',
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              fontSize: '16px',
              color: '#64748b',
              padding: '4px',
            }}
            aria-label="検索をクリア"
          >
            ×
          </button>
        )}
      </div>
      <div className="table-container">
        <table className="employee-table" style={{ tableLayout: 'fixed' }}>
          <thead>
            <tr>
              <th
                className={getSortClass('id')}
                onClick={() => onSort('id')}
                aria-sort={getAriaSort('id')}
                style={{ width: '15%' }}
              >
                ID
              </th>
              <th
                className={getSortClass('name')}
                onClick={() => onSort('name')}
                aria-sort={getAriaSort('name')}
                style={{ width: '35%' }}
              >
                名前
              </th>
              <th
                className={getSortClass('department')}
                onClick={() => onSort('department')}
                aria-sort={getAriaSort('department')}
                style={{ width: '35%' }}
              >
                部署
              </th>
              <th
                className={getSortClass('age')}
                onClick={() => onSort('age')}
                aria-sort={getAriaSort('age')}
                style={{ width: '15%' }}
              >
                年齢
              </th>
            </tr>
          </thead>
          <tbody>
            {employees.length === 0 ? (
              <tr>
                <td colSpan={4} className="no-results">
                  該当する社員が見つかりません
                </td>
              </tr>
            ) : (
              employees.map((emp) => (
                <tr key={emp.id}>
                  <td style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {emp.id}
                  </td>
                  <td style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {emp.name}
                  </td>
                  <td style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {emp.department}
                  </td>
                  <td style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {emp.age}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { Employee, SortableField } from './types';
import EmployeeTable from './EmployeeTable';

const initialEmployees: Employee[] = [
  { id: 1, name: '佐藤 健', department: '開発部', age: 28, email: 'sato@example.com', hireDate: '2020-04-01' },
  { id: 2, name: '鈴木 美咲', department: '人事部', age: 34, email: 'suzuki@example.com', hireDate: '2018-10-15' },
  { id: 3, name: '高橋 航', department: '営業部', age: 41, email: 'takahashi@example.com', hireDate: '2015-04-01' },
  { id: 4, name: '田中 葵', department: '開発部', age: 25, email: 'tanaka@example.com', hireDate: '2022-04-01' },
  { id: 5, name: '伊藤 蓮', department: 'マーケティング部', age: 30, email: 'ito@example.com', hireDate: '2019-07-01' },
  { id: 6, name: '渡辺 さくら', department: '営業部', age: 27, email: 'watanabe@example.com', hireDate: '2021-04-01' },
  { id: 7, name: '山本 大地', department: '総務部', age: 45, email: 'yamamoto@example.com', hireDate: '2012-04-01' },
  { id: 8, name: '中村 陽菜', department: '開発部', age: 29, email: 'nakamura@example.com', hireDate: '2020-10-01' },
  { id: 9, name: '小林 翔', department: 'マーケティング部', age: 33, email: 'kobayashi@example.com', hireDate: '2017-04-01' },
  { id: 10, name: '加藤 美優', department: '人事部', age: 26, email: 'kato@example.com', hireDate: '2021-10-01' },
];

export default function App() {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const [filterText, setFilterText] = useState(() => {
    const params = new URLSearchParams(window.location.search);
    return params.get('filter') || '';
  });

  const [sortField, setSortField] = useState<SortableField>(() => {
    const params = new URLSearchParams(window.location.search);
    const field = params.get('sortField') as SortableField;
    return field && ['id', 'name', 'department', 'age'].includes(field) ? field : 'id';
  });

  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>(() => {
    const params = new URLSearchParams(window.location.search);
    const dir = params.get('sortDirection');
    return dir === 'desc' ? 'desc' : 'asc';
  });

  const [currentPage, setCurrentPage] = useState(() => {
    const params = new URLSearchParams(window.location.search);
    const page = parseInt(params.get('page') || '1', 10);
    return isNaN(page) ? 1 : page;
  });

  const itemsPerPage = 5;

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError(null);

    const timer = setTimeout(() => {
      try {
        setEmployees(initialEmployees);
        setLoading(false);
      } catch (err) {
        setError('データの取得に失敗しました。');
        setLoading(false);
      }
    }, 400);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, []);

  useEffect(() => {
    const params = new URLSearchParams();
    if (filterText) params.set('filter', filterText);
    if (sortField !== 'id') params.set('sortField', sortField);
    if (sortDirection !== 'asc') params.set('sortDirection', sortDirection);
    if (currentPage > 1) params.set('page', String(currentPage));

    const query = params.toString();
    const newUrl = query ? `?${query}` : window.location.pathname;
    window.history.replaceState(null, '', newUrl);
  }, [filterText, sortField, sortDirection, currentPage]);

  const handleSort = (field: SortableField) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
    setCurrentPage(1);
  };

  const handleFilterChange = (text: string) => {
    setFilterText(text);
    setCurrentPage(1);
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const filtered = employees.filter((emp) =>
      emp.name.toLowerCase().includes(filterText.toLowerCase())
    );

    return filtered.sort((a, b) => {
      const aVal = a[sortField];
      const bVal = b[sortField];

      if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });
  }, [employees, filterText, sortField, sortDirection]);

  const totalPages = Math.ceil(filteredAndSortedEmployees.length / itemsPerPage) || 1;

  const paginatedEmployees = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredAndSortedEmployees.slice(start, start + itemsPerPage);
  }, [filteredAndSortedEmployees, currentPage, itemsPerPage]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">社員一覧</h1>
      </header>
      {loading ? (
        <div className="no-results">読み込み中...</div>
      ) : error ? (
        <div className="no-results" style={{ color: '#ef4444' }}>{error}</div>
      ) : (
        <>
          <EmployeeTable
            employees={paginatedEmployees}
            sortField={sortField}
            sortDirection={sortDirection}
            onSort={handleSort}
            filterText={filterText}
            onFilterChange={handleFilterChange}
          />
          {totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: '16px', gap: '12px' }}>
              <button
                type="button"
                onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
                disabled={currentPage === 1}
                style={{ padding: '6px 12px', cursor: currentPage === 1 ? 'not-allowed' : 'pointer' }}
              >
                前へ
              </button>
              <span>{currentPage} / {totalPages}</span>
              <button
                type="button"
                onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
                disabled={currentPage === totalPages}
                style={{ padding: '6px 12px', cursor: currentPage === totalPages ? 'not-allowed' : 'pointer' }}
              >
                次へ
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
